function getUserIdFromJwt(token) {
    const payloadB64 = token.split(".")[1];
    const base64 = payloadB64.replace(/-/g, "+").replace(/_/g, "/");
    const padded = base64 + "=".repeat((4 - base64.length % 4) % 4);
    const payload = JSON.parse(atob(padded));
    return payload.sub;
}

