// Dynamic requested_at via direct string replacement — avoids JSON.parse/stringify
// round-tripping the whole body, which silently rewrites "51.0" as "51" and trips
// the backend's NUMBER_DECIMAL check on `amount`.
const jitterMs = Math.floor(Math.random() * 5000); // up to +5s
const requestedAt = new Date(Date.now() + jitterMs).toISOString().replace(/\.\d{3}Z$/, "");

const updatedBody = pm.request.body.raw.replace(
    /"requested_at"\s*:\s*"[^"]*"/,
    `"requested_at": "${requestedAt}"`
);

pm.request.body.update(updatedBody);

