{
  "name": "{{apps_item_name}}"
  "type": [
    "adex:Apps"
  ],
  "label": "AI-Powered Medical Imaging Diagnostics for Lung Conditions",
  "tags": [
    "healthcare",
    "diagnostics",
    "medical imaging",
    "AI"
  ],
  "industry": "Healthcare",
  "shortDescription": "AI-driven diagnostics platform for detecting lung conditions using chest X-rays.",
  "description": "This use case showcases the application of deep learning algorithms for interpreting chest radiographs, aiding in the timely diagnosis of lung conditions such as TB, COPD, and lung cancer.",
  "organizationType": "Public",
  "accessPolicy": "OPEN",
  "sections": [
    {
      "title": "Introduction",
      "content": "Across each procurement season, thousands of Paddy Procurement Centres (PPCs) deliver grain to a large, province-wide network of registered rice mills. Pairings are still set by manual judgement and legacy rules, which leaves spare milling capacity idle, lengthens haul distances, and makes equity goals harder to track. The rich operational data already flowing through the Online Procurement Management System (OPMS) can anchor a smarter, policy-aligned network design that balances workload, curbs transport cost, and surfaces bottlenecks before they bite."
    },
    {
      "title": "Current Opportunities for Improvement",
      "subsections": [
        { "subtitle": "Limited foresight", "points": ["Arrival patterns and mill capacities are understood only after trucks roll, forcing reactive fixes."] },
        { "subtitle": "Heuristic pairing", "points": ["Village-to-PPC and PPC-to-mill tags seldom explore alternatives that would shorten routes or absorb latent capacity."] },
        { "subtitle": "Equity & compliance friction", "points": ["Mandal-level service targets and caps on cross-district movement demand painstaking manual checks."] },
        { "subtitle": "Adaptation lag", "points": ["Weather shifts or labour disruptions require rapid rerouting, yet the present process is paperwork-heavy and opaque to headquarters."] }
      ]
    },
    {
      "title": "Proposed Methodology",
      "subsections": [
        { "subtitle": "Predictive baselining", "points": ["Mine past OPMS feeds to forecast realistic volumes at each PPC before peak arrival."] },
        { "subtitle": "Scenario stress-testing", "points": ["Generate multiple demand scenarios so policy makers can gauge how robust any allocation is under plausible swings."] },
        { "subtitle": "Multi-objective optimisation", "points": ["Search for assignments that minimise haul distance while balancing mill utilisation and locking in policy constraints such as entitlement ceilings and district quotas."] },
        { "subtitle": "Human-in-the-loop validation", "points": ["District officers review suggested pairings, lock or override as needed; the engine then re-optimises around those choices and logs rationale for audit."] },
        { "subtitle": "Continuous learning", "points": ["Daily variances feed back to refine forecasts and flag when reallocation would materially improve cost or compliance."] }
      ]
    },
    {
      "title": "Proposed Technological Solutions",
      "subsections": [
        { "subtitle": "Demand-forecast micro-service", "points": ["A lightweight temporal model that turns OPMS history into daily PPC arrival projections."] },
        { "subtitle": "Optimisation core", "points": ["A solver that blends exact and heuristic techniques, exposed through open APIs."] },
        { "subtitle": "Policy rule layer", "points": ["Declarative constraints so new mandates can be toggled without touching code."] },
        { "subtitle": "Decision dashboard", "points": ["GIS visual of proposed pairings, expected distance savings, and override controls."] },
        { "subtitle": "OPMS integration", "points": ["Two-way data bridge so staff work inside the system they already know."] }
      ]
    },
    {
      "title": "Key Objectives / Performance Metrics",
      "subsections": [
        { "subtitle": "Reduced Transport Distance", "points": ["Lower total tonne-kilometres moved across the state."] },
        { "subtitle": "Balanced Mill Utilisation", "points": ["Narrow the gap between over- and under-loaded mills, improving asset productivity."] },
        { "subtitle": "Equity Assurance", "points": ["Demonstrably meet mandal-level service targets built into the constraint set."] },
        { "subtitle": "Operational Agility", "points": ["Shorter response time when shocks demand rerouting, with fewer manual work-arounds."] },
        { "subtitle": "Transparency & Auditability", "points": ["Every allocation and override traceable in a single digital trail."] }
      ]
    }
  ]
}

