// --- Filter field check: only id, type, resourceServer should be present ---
pm.test("Each result only contains the requested filter fields", function () {
    const jsonData = pm.response.json();
    const allowedFields = ["id", "type", "resourceServer"];
    jsonData.result.forEach(function (item) {
        const keys = Object.keys(item);
        keys.forEach(function (key) {
            pm.expect(allowedFields).to.include(key);
        });
    });
});

// --- Search criteria check: at least one resourceServer.url must match the searched value ---
// (a result can have multiple resourceServer entries, e.g. NGSI-LD + FILE;
// only one of them needs to match for the result to be a valid match)
pm.test("Every result has at least one resourceServer.url matching the search value", function () {
    const jsonData = pm.response.json();
    const requestBody = JSON.parse(pm.request.body.raw);
    const expectedUrl = requestBody.searchCriteria[0].values[0];

    jsonData.result.forEach(function (item) {
        pm.expect(item.resourceServer).to.be.an("array").that.is.not.empty;
        const urls = item.resourceServer.map(function (rs) { return rs.url; });
        pm.expect(urls).to.include(expectedUrl);
    });
});

// --- Pagination checks ---
pm.test("paginationInfo is present and internally consistent", function () {
    const jsonData = pm.response.json();
    const p = jsonData.paginationInfo;

    pm.expect(p).to.be.an("object");
    pm.expect(p.page).to.be.a("number");
    pm.expect(p.size).to.be.a("number");
    pm.expect(p.totalCount).to.be.a("number");
    pm.expect(p.totalPages).to.eql(Math.ceil(p.totalCount / p.size));

    // result length should equal `size`, except possibly on the last page
    const isLastPage = p.page === p.totalPages;
    if (!isLastPage) {
        pm.expect(jsonData.result.length).to.eql(p.size);
    } else {
        const expectedLastPageCount = p.totalCount - (p.totalPages - 1) * p.size;
        pm.expect(jsonData.result.length).to.eql(expectedLastPageCount);
    }

    pm.expect(p.hasPrevious).to.eql(p.page > 1);
    pm.expect(p.hasNext).to.eql(p.page < p.totalPages);
});

