function decodeJWT(token) {
    const payload = token.split(".")[1];
    const padded = payload + "=".repeat((4 - payload.length % 4) % 4);
    const base64 = padded.replace(/-/g, "+").replace(/_/g, "/");
    const decoded = decodeURIComponent(
        atob(base64)
            .split("")
            .map(c => "%" + ("00" + c.charCodeAt(0).toString(16)).slice(-2))
            .join("")
    );
    return JSON.parse(decoded);
}

pm.test("POSITIVE: Auto-extract consumer_org_id from JWT claims (informational only)", function () {
    const token = json.access_token;
    try {
        const claims = decodeJWT(token);
        if (claims.organisation_id) {
            pm.environment.set("consumer_org_id", claims.organisation_id);
            console.log("Saved consumer_org_id from JWT (does NOT overwrite org_id):", claims.organisation_id);
        } else {
            console.log("No organisation_id claim in token yet — user may not have joined an org.");
        }
    } catch (e) {
        console.log("Could not decode token:", e.message);
    }
});

